// Some portions generated by Codex
import assert from 'node:assert/strict';
import test from 'node:test';
import { labelHoverBridge } from '../../../main/frontend/graph-explorer/graph-hover.ts';

function corners(rectangle) {
  return [-1, 1].flatMap(x => [-1, 1].map(y => ({
    x: rectangle.x + x * rectangle.width / 2,
    y: rectangle.y + y * rectangle.height / 2
  })));
}

function contains(polygon, point) {
  return polygon.length >= 3 && polygon.every((a, index) => {
    const b = polygon[(index + 1) % polygon.length];
    return (b.x - a.x) * (point.y - a.y) - (b.y - a.y) * (point.x - a.x) >= -1e-7;
  });
}

test('label hover bridges are finite bounded deterministic symmetric convex joins', () => {
  const node = {x: 512, y: 164, width: 180, height: 46};
  for (const label of [{x: 355, y: 113, width: 62, height: 23},
    {x: 250, y: 164, width: 62, height: 23}, {x: 512, y: -100, width: 62, height: 23},
    {x: 512, y: 500, width: 2000, height: 10}, {...node},
    {...node, width: 10, height: 10}, {...node, x: 650, y: 200}]) {
    const points = labelHoverBridge(node, label);
    assert.ok(points.length >= 4 && points.length <= 8);
    assert.ok(points.every(point => Number.isFinite(point.x) && Number.isFinite(point.y)));
    const targets = [...corners(node), ...corners(label)];
    assert.ok(points.every(point => targets.some(target => target.x === point.x && target.y === point.y)),
      'the join adds no points beyond actual target corners');
    assert.ok(targets.every(point => contains(points, point)), 'both complete targets are inside the join');
    assert.deepEqual(labelHoverBridge(node, label), points, 'geometry is deterministic');
    assert.deepEqual(labelHoverBridge(label, node), points, 'target order does not change the join');
  }
});

test('off-center straight transfers stay inside the join in every direction and with diagonal overlap', () => {
  const node = {x: 0, y: 0, width: 100, height: 40};
  for (const x of [-120, 0, 120]) {
    for (const y of [-80, 0, 80]) {
      const label = {x, y, width: 40, height: 20};
      const polygon = labelHoverBridge(node, label);
      for (const from of corners(node)) {
        for (const to of corners(label)) {
          for (let step = 1; step < 8; step++) {
            const fraction = step / 8;
            const point = {x: from.x + (to.x - from.x) * fraction, y: from.y + (to.y - from.y) * fraction};
            assert.ok(contains(polygon, point), `transfer ${JSON.stringify({from, to, point})} stays reachable`);
          }
        }
      }
    }
  }
  const overlapping = {x: 60, y: 20, width: 40, height: 20};
  const overlapHull = labelHoverBridge(node, overlapping);
  assert.ok(contains(overlapHull, {x: 0, y: 25}),
    'a straight transfer across the nonconvex union of diagonally overlapping targets remains reachable');
});

test('invalid or unrepresentable target rectangles have no hover bridge', () => {
  const node = {x: 0, y: 0, width: 100, height: 40};
  for (const label of [{...node, x: Infinity}, {...node, y: NaN},
    {...node, width: 0}, {...node, height: -1}, {...node, width: Infinity},
    {...node, x: Number.MAX_VALUE, width: Number.MAX_VALUE}]) {
    assert.deepEqual(labelHoverBridge(node, label), []);
    assert.deepEqual(labelHoverBridge(label, node), []);
  }
});
